// factsGolden is testdata/facts-golden.json, generated by testdata/facts-gen.exs from the
// Elixir Kogen: the bytes and values its modules produced for the inputs the tests replay.
type factsGolden struct {
	ConfigDigests []struct{ Text, Digest string }  `json:"config_digests"`
	JSON          []struct{ Input, Output string } `json:"json"`
	Comparison    []struct {
		Text   string
		Result struct {
			Ok    *string
			Error *struct {
				Class, Reason, Detail string
				Exit                  int
			}
		}
	}
	Repo struct {
		Files, Untracked map[string]string
		Slug, Head       string
		State            struct {
			Request    string
			SourcePath string `json:"source_path"`
			Rounds     []map[string]any
			Origin     SourceOrigin
		}
		ContractSHA256 string `json:"contract_sha256"`
		Captured       string
		PackageValid   string `json:"package_valid"`
		PackageInvalid string `json:"package_invalid"`
		GitDirHash     string `json:"git_dir_hash"`
		Refine         struct {
			Correction     SourceRequest
			Ref            map[string]any
			Refined        string
			ContractSHA256 string            `json:"contract_sha256"`
			DirFiles       map[string]string `json:"dir_files"`
			DirModes       map[string]int    `json:"dir_modes"`
			RefinedTwice   string            `json:"refined_twice"`
			Card           string
		}
	}
}

func loadFactsGolden(t *testing.T) *factsGolden {
	t.Helper()
	b, err := os.ReadFile("testdata/facts-golden.json")
	if err != nil {
		t.Fatal(err)
	}
	dec := json.NewDecoder(bytes.NewReader(b))
	dec.UseNumber()
	var g factsGolden
	if err := dec.Decode(&g); err != nil {
		t.Fatal(err)
	}
	return &g
}

func sha256Of(s string) string {
	sum := sha256.Sum256([]byte(s))
	return hex.EncodeToString(sum[:])
}

func TestCheckoutResolvesSymlinksAndHashesGitDir(t *testing.T) {
	root := gitRepo(t)
	physical, err := filepath.EvalSymlinks(root)
	if err != nil {
		t.Fatal(err)
	}
	link := filepath.Join(t.TempDir(), "link")
	if err := os.Symlink(root, link); err != nil {
		t.Fatal(err)
	}
	nested := filepath.Join(root, "a", "b")
	if err := os.MkdirAll(nested, 0o755); err != nil {
		t.Fatal(err)
	}
	for _, dir := range []string{root, link} {
		got, err := Checkout(dir)
		if err != nil {
			t.Fatal(err)
		}
		want := CheckoutFacts{Root: physical, GitDir: filepath.Join(physical, ".git"), ID: sha256Of(filepath.Join(physical, ".git"))}
		if got != want {
			t.Errorf("Checkout(%s) = %+v, want %+v", dir, got, want)
		}
	}
	// From a subdirectory the root is the directory asked for, as `pwd -P` there prints it;
	// the Git directory is still the repository's.
	got, err := Checkout(nested)
	if err != nil {
		t.Fatal(err)
	}
	if got.Root != filepath.Join(physical, "a", "b") || got.GitDir != filepath.Join(physical, ".git") {
		t.Errorf("nested = %+v", got)
	}
}

func TestCheckoutLinkedWorktreesHaveSeparateIdentities(t *testing.T) {
	root := gitRepo(t)
	writeFile(t, root, "f.txt", "x\n")
	git(t, root, "add", "-A")
	git(t, root, "commit", "-q", "-m", "init")
	wt := filepath.Join(t.TempDir(), "wt")
	git(t, root, "worktree", "add", "-q", wt, "-b", "side")
	main, err := Checkout(root)
	if err != nil {
		t.Fatal(err)
	}
	side, err := Checkout(wt)
	if err != nil {
		t.Fatal(err)
	}
	if main.ID == side.ID || main.GitDir == side.GitDir || main.Root == side.Root {
		t.Fatalf("main %+v and worktree %+v are not separate checkouts", main, side)
	}
	if !strings.HasPrefix(side.GitDir, main.GitDir+string(filepath.Separator)+"worktrees"+string(filepath.Separator)) {
		t.Errorf("worktree git dir %s", side.GitDir)
	}
	if side.ID != sha256Of(side.GitDir) {
		t.Errorf("worktree id %s", side.ID)
	}
}

func TestCheckoutFailsOutsideARepositoryAndForMissingDirectories(t *testing.T) {
	gitSandbox(t)
	t.Setenv("GIT_CEILING_DIRECTORIES", filepath.Dir(t.TempDir()))
	if _, err := Checkout(t.TempDir()); err == nil {
		t.Error("a directory outside any repository has no checkout")
	}
	if _, err := Checkout(filepath.Join(t.TempDir(), "missing")); err == nil {
		t.Error("a missing directory has no checkout")
	}
}

func TestOwnerNamesThisProcessAndLockToken(t *testing.T) {
	o, err := Owner("tok-1")
	if err != nil {
		t.Fatal(err)
	}
	if o.PID != os.Getpid() || o.Token == nil || *o.Token != "tok-1" {
		t.Fatalf("owner %+v", o)
	}
	// `ps -o lstart=` prints e.g. "Thu Oct 22 16:48:03 2026".
	want, err := exec.Command("ps", "-p", strconv.Itoa(os.Getpid()), "-o", "lstart=").Output()
	if err != nil {
		t.Fatal(err)
	}
	if o.Birth == "" || o.Birth != strings.TrimSpace(string(want)) || len(strings.Fields(o.Birth)) != 5 {
		t.Errorf("birth %q, ps says %q", o.Birth, want)
	}
	b, err := EncodeJSON(o)
	if err != nil {
		t.Fatal(err)
	}
	if want := `{"birth":` + strconv.Quote(o.Birth) + `,"pid":` + strconv.Itoa(o.PID) + `,"token":"tok-1"}`; string(b) != want {
		t.Errorf("owner JSON %s, want %s", b, want)
	}

	none, err := Owner("")
	if err != nil {
		t.Fatal(err)
	}
	if none.Token != nil {
		t.Errorf("no lock must record a null token: %+v", none)
	}
	if b, _ := EncodeJSON(none); !strings.Contains(string(b), `"token":null`) {
		t.Errorf("no-lock owner JSON %s", b)
	}
}

func TestEncodeJSONMatchesElixirJSONEncode(t *testing.T) {
	g := loadFactsGolden(t)
	if len(g.JSON) < 7 {
		t.Fatalf("only %d pinned encodings", len(g.JSON))
	}
	for _, c := range g.JSON {
		v, err := decodeJSON([]byte(c.Input))
		if err != nil {
			t.Fatalf("%s: %v", c.Input, err)
		}
		got, err := EncodeJSON(v)
		if err != nil {
			t.Fatal(err)
		}
		if string(got) != c.Output {
			t.Errorf("%s\n got %s\nwant %s", c.Input, got, c.Output)
		}
	}
}

func TestEncodeJSONValues(t *testing.T) {
	type rec struct {
		Name  string   `json:"name"`
		Items []string `json:"items"`
		Ptr   *string  `json:"ptr"`
	}
	cases := []struct {
		in   any
		want string
	}{
		{nil, `null`},
		{true, `true`},
		{42, `42`},
		{int64(-7), `-7`},
		{json.Number("12345678901234567890"), `12345678901234567890`},
		{[]string{}, `[]`},
		{[]string{"a", "b\n"}, `["a","b\n"]`},
		{map[string]string{"z": "1", "a": "2"}, `{"a":"2","z":"1"}`},
		{[]map[string]any{{"b": 1, "a": nil}}, `[{"a":null,"b":1}]`},
		{rec{Name: "n<&>", Items: []string{"x"}}, `{"items":["x"],"name":"n<&>","ptr":null}`},
		{"  \x7f \x1f é", "\"  \x7f \\u001F é\""},
	}
	for _, c := range cases {
		got, err := EncodeJSON(c.in)
		if err != nil {
			t.Errorf("%#v: %v", c.in, err)
			continue
		}
		if string(got) != c.want {
			t.Errorf("%#v = %s, want %s", c.in, got, c.want)
		}
	}
	for _, bad := range []any{"a\xffb", map[string]any{"k": "\xc3"}, map[string]any{"\xff": 1}, []string{"\xfe"}, make(chan int)} {
		if _, err := EncodeJSON(bad); err == nil {
			t.Errorf("%#v encoded", bad)
		}
	}
}

func TestWriteJSONAtomicNeverTearsUnderConcurrentReaders(t *testing.T) {
	path := filepath.Join(t.TempDir(), "context.json")
	if err := WriteJSONAtomic(path, map[string]any{"n": 0}); err != nil {
		t.Fatal(err)
	}
	stop := make(chan struct{})
	var wg sync.WaitGroup
	torn := make(chan string, 1)
	wg.Add(1)
	go func() {
		defer wg.Done()
		for {
			select {
			case <-stop:
				return
			default:
			}
			b, err := os.ReadFile(path)
			if err != nil || !json.Valid(b) || !bytes.HasSuffix(b, []byte("\n")) {
				select {
				case torn <- string(b):
				default:
				}
				return
			}
		}
	}()
	for i := 1; i <= 300; i++ {
		if err := WriteJSONAtomic(path, map[string]any{"n": i, "pad": strings.Repeat("x", i*10)}); err != nil {
			t.Fatal(err)
		}
	}
	close(stop)
	wg.Wait()
	select {
	case b := <-torn:
		t.Fatalf("a reader saw a torn file: %.80q", b)
	default:
	}
	if _, err := os.Stat(path + ".tmp"); !os.IsNotExist(err) {
		t.Errorf("temporary file left behind: %v", err)
	}
}

// packageDoc reads a package facts file as a value, with the checkout id taken out.
func packageDoc(t *testing.T, raw string) (map[string]any, string) {
	t.Helper()
	var doc map[string]any
	if err := json.Unmarshal([]byte(raw), &doc); err != nil {
		t.Fatalf("%v: %s", err, raw)
	}
	id, _ := doc["checkout_id"].(string)
	delete(doc, "checkout_id")
	return doc, id
}

func TestWritePackageFactsMatchesElixirLocalFactsPackage(t *testing.T) {
	g := loadFactsGolden(t)
	root := provenanceFixture(t, g)
	cfg, err := LoadConfig(root)
	if err != nil {
		t.Fatal(err)
	}
	checkout, err := Checkout(root)
	if err != nil {
		t.Fatal(err)
	}
	for _, c := range []struct{ slug, want string }{
		{g.Repo.Slug, g.Repo.PackageValid},
		{"broken", g.Repo.PackageInvalid},
	} {
		if err := WritePackageFacts(root, c.slug, cfg); err != nil {
			t.Fatal(err)
		}
		raw, err := os.ReadFile(filepath.Join(root, ".kogen/local/packages", c.slug+".json"))
		if err != nil {
			t.Fatal(err)
		}
		if !bytes.HasSuffix(raw, []byte("\n")) {
			t.Errorf("%s: no final newline", c.slug)
		}
		got, id := packageDoc(t, string(raw))
		want, wantID := packageDoc(t, c.want)
		if !reflect.DeepEqual(got, want) {
			t.Errorf("%s\n got %v\nwant %v", c.slug, got, want)
		}
		if id != checkout.ID || id != sha256Of(checkout.GitDir) {
			t.Errorf("%s: checkout_id %s, want %s", c.slug, id, checkout.ID)
		}
		if wantID != g.Repo.GitDirHash {
			t.Errorf("golden is inconsistent: %s", wantID)
		}
	}
}

func TestWritePackageFactsRecordsSortedPathsHashAndState(t *testing.T) {
	root := gitRepo(t)
	writeFile(t, root, ".gitignore", "")
	writeFile(t, root, ConfigPath, "version: 1\nprotect:\n  - 'z.cfg'\n  - 'a.cfg'\n")
	writeFile(t, root, "z.cfg", "z\n")
	writeFile(t, root, "a.cfg", "a\n")
	writeFile(t, root, FeaturePath(demoSlug), goodFeature)
	writeFile(t, root, IntentMDPath(demoSlug), demoMD(demoParts{}))
	cfg := mustParse(t, "version: 1\nprotect:\n  - 'z.cfg'\n  - 'a.cfg'\n")

	read := func() (doc struct {
		CheckoutID   string   `json:"checkout_id"`
		Paths        []string `json:"paths"`
		SHA256       string   `json:"sha256"`
		PackageState string   `json:"package_state"`
	}) {
		t.Helper()
		if err := WritePackageFacts(root, demoSlug, cfg); err != nil {
			t.Fatal(err)
		}
		b, err := os.ReadFile(filepath.Join(root, ".kogen/local/packages/"+demoSlug+".json"))
		if err != nil {
			t.Fatal(err)
		}
		if err := json.Unmarshal(b, &doc); err != nil {
			t.Fatal(err)
		}
		return doc
	}

	doc := read()
	if !slices.IsSorted(doc.Paths) || !slices.Contains(doc.Paths, "a.cfg") || !slices.Contains(doc.Paths, ConfigPath) {
		t.Errorf("paths %q", doc.Paths)
	}
	if doc.SHA256 != Hash(root, doc.Paths) || doc.PackageState != "valid" || doc.CheckoutID == "" {
		t.Errorf("doc %+v", doc)
	}

	// A change to a baseline file changes the hash; a broken Intent makes the package invalid
	// while its facts are still written.
	before := doc.SHA256
	writeFile(t, root, "a.cfg", "changed\n")
	writeFile(t, root, FeaturePath(demoSlug), "this is not Gherkin\n")
	broken := read()
	if broken.SHA256 == before || broken.PackageState != "invalid" {
		t.Errorf("broken %+v", broken)
	}
}

func TestWritePackageFactsReplacesOnlyItsFileAndLeavesNoTemporary(t *testing.T) {
	root := gitRepo(t)
	writeFile(t, root, ConfigPath, "version: 1\n")
	writeFile(t, root, IntentMDPath("x"), "# X\n")
	cfg := mustParse(t, "version: 1\n")
	dir := filepath.Join(root, ".kogen/local/packages")
	writeFile(t, root, ".kogen/local/packages/other.json", "keep\n")
	for i := 0; i < 3; i++ {
		if err := WritePackageFacts(root, "x", cfg); err != nil {
			t.Fatal(err)
		}
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		t.Fatal(err)
	}
	var names []string
	for _, e := range entries {
		names = append(names, e.Name())
	}
	if !slices.Equal(names, []string{"other.json", "x.json"}) {
		t.Errorf("packages folder holds %q", names)
	}
	if b, _ := os.ReadFile(filepath.Join(dir, "other.json")); string(b) != "keep\n" {
		t.Errorf("another package's facts changed: %q", b)
	}
}

func TestWritePackageFactsErrors(t *testing.T) {
	gitSandbox(t)
	t.Setenv("GIT_CEILING_DIRECTORIES", filepath.Dir(t.TempDir()))
	cfg := mustParse(t, "version: 1\n")
	outside := t.TempDir()
	writeFile(t, outside, ConfigPath, "version: 1\n")
	if err := WritePackageFacts(outside, "x", cfg); err == nil {
		t.Error("facts of a directory outside a repository")
	}
	if _, err := os.Stat(filepath.Join(outside, ".kogen/local/packages/x.json")); !os.IsNotExist(err) {
		t.Errorf("a file was written anyway: %v", err)
	}
	if err := WritePackageFacts(filepath.Join(outside, "missing"), "x", cfg); err == nil {
		t.Error("facts of a missing directory")
	}
}
